}

.message-textarea::placeholder {
    color: #72767d;
}

.message-textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

.btn-send {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 10px 18px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-send:hover:not(:disabled) {
    background: #4752c4;
}

.btn-send:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

